// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(address actor, uint256 amount, uint256 warpTo, uint256 unlockParam) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(unlockParam <= type(uint256).max - warpTo);
        amount = bound(amount, 1, 1000 ether);
        warpTo = bound(warpTo, 1, 2 ** 128);
        unlockParam = bound(unlockParam, warpTo + 1, warpTo + 2 ** 64);
        vm.warp(warpTo);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockParam);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
